<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #111827;
      --panel-2: #1b2437;
      --border: rgba(255, 255, 255, 0.10);
      --text: #e5e7eb;
      --muted: #9ca3af;
      --accent: #ef4444;
      --accent-hover: #f87171;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(99, 102, 241, 0.18), transparent 34%),
        linear-gradient(180deg, #060913 0%, var(--bg) 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    .app {
      width: min(920px, 100%);
    }

    .card {
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(10, 15, 28, 0.96));
      border: 1px solid var(--border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .preview {
      padding: 24px;
      display: grid;
      gap: 20px;
    }

    .image-shell {
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
      border: 1px solid var(--border);
      border-radius: 20px;
      padding: 16px;
    }

    .image {
      width: 100%;
      aspect-ratio: 16 / 10;
      border-radius: 14px;
      display: block;
      object-fit: cover;
      background: #0f172a;
    }

    .meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      flex-wrap: wrap;
    }

    .title {
      margin: 0;
      font-size: clamp(1.4rem, 2vw, 1.8rem);
      font-weight: 700;
    }

    .subtitle {
      margin: 6px 0 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .actions {
      display: flex;
      gap: 12px;
      margin-top: 8px;
    }

    button {
      font: inherit;
      border: 0;
      cursor: pointer;
      transition: transform 120ms ease, background-color 120ms ease, border-color 120ms ease;
    }

    button:focus-visible {
      outline: 2px solid #93c5fd;
      outline-offset: 3px;
    }

    .btn {
      padding: 12px 18px;
      border-radius: 12px;
      background: var(--panel-2);
      color: var(--text);
      border: 1px solid var(--border);
      font-weight: 600;
    }

    .btn:hover { transform: translateY(-1px); }

    .btn-danger {
      background: linear-gradient(180deg, #dc2626, #b91c1c);
      border-color: rgba(255, 255, 255, 0.08);
    }

    .btn-danger:hover {
      background: linear-gradient(180deg, #ef4444, #dc2626);
    }

    dialog {
      width: min(92vw, 520px);
      border: 1px solid var(--border);
      border-radius: 22px;
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(8, 11, 20, 0.98));
      color: var(--text);
      box-shadow: var(--shadow);
      padding: 0;
    }

    dialog::backdrop {
      background: rgba(2, 6, 23, 0.78);
      backdrop-filter: blur(8px);
    }

    .modal {
      padding: 24px;
    }

    .modal h2 {
      margin: 0 0 10px;
      font-size: 1.4rem;
    }

    .modal p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 24px;
    }

    .btn-ghost {
      background: transparent;
      border: 1px solid var(--border);
      color: var(--text);
    }

    .btn-ghost:hover {
      background: rgba(255, 255, 255, 0.05);
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script>
    const h = (tag, props = {}, ...children) => {
      const el = document.createElement(tag);
      for (const [key, value] of Object.entries(props)) {
        if (key === "className") el.className = value;
        else if (key === "textContent") el.textContent = value;
        else if (key.startsWith("on") && typeof value === "function") {
          el.addEventListener(key.slice(2).toLowerCase(), value);
        } else if (value !== false && value != null) {
          el.setAttribute(key, value);
        }
      }
      for (const child of children.flat()) {
        el.append(child instanceof Node ? child : document.createTextNode(child));
      }
      return el;
    };

    function ConfirmDeleteDialog({ onConfirm }) {
      const dialog = h(
        "dialog",
        { "aria-labelledby": "delete-title", "aria-describedby": "delete-description" },
        h("div", { className: "modal" },
          h("h2", { id: "delete-title", textContent: "Delete this image?" }),
          h("p", { id: "delete-description", textContent: "This will remove the image from your library. You can’t undo this action." }),
          h("div", { className: "modal-actions" },
            h("button", { type: "button", className: "btn btn-ghost", "data-close": "true", textContent: "Cancel" }),
            h("button", { type: "button", className: "btn btn-danger", "data-confirm": "true", textContent: "Delete image" })
          )
        )
      );

      dialog.addEventListener("click", (event) => {
        if (event.target === dialog) dialog.close();
      });

      dialog.querySelector('[data-close="true"]').addEventListener("click", () => dialog.close());
      dialog.querySelector('[data-confirm="true"]').addEventListener("click", () => {
        onConfirm();
        dialog.close();
      });

      return dialog;
    }

    function ImagePreview() {
      const root = h("main", { className: "app" });
      const card = h("section", { className: "card" });
      const preview = h("div", { className: "preview" });

      const image = h("img", {
        className: "image",
        src: "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1600&q=80",
        alt: "Preview of a library image"
      });

      const dialog = ConfirmDeleteDialog({
        onConfirm: () => alert("Image deleted from your library.")
      });

      const trigger = h("button", {
        type: "button",
        className: "btn btn-danger trigger",
        textContent: "Delete",
        onClick: () => dialog.showModal()
      });

      preview.append(
        h("div", { className: "image-shell" }, image),
        h("div", { className: "meta" },
          h("div", {},
            h("h1", { className: "title", textContent: "Mountain Lake" }),
            h("p", { className: "subtitle", textContent: "A high-resolution preview from your image library." })
          ),
          h("div", { className: "actions" }, trigger)
        )
      );

      card.append(preview, dialog);
      root.append(card);
      return root;
    }

    document.getElementById("root").appendChild(ImagePreview());
  </script>
</body>
</html>
